<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';use App\Admin;
Admin::requirePermission('orders.view');$status=(string)($_GET['status']??'');$allowed=['new','reviewing','accepted','preparing','ready','completed','rejected','cancelled'];$sql="SELECT o.id,o.order_number,o.status,o.total,o.fulfillment_method,o.created_at,c.full_name,c.phone FROM orders o JOIN customers c ON c.id=o.customer_id";$params=[];if(in_array($status,$allowed,true)){$sql.=" WHERE o.status=?";$params[]=$status;}$sql.=" ORDER BY o.id DESC LIMIT 300";$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>الطلبات | الفخامة</title><link rel="stylesheet" href="../assets/css/store.css"><style>.wrap{max-width:1200px;margin:30px auto;padding:0 16px}.panel{background:#111;border:1px solid #49371c;border-radius:14px;padding:18px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.filters a{border:1px solid #49371c;border-radius:20px;padding:6px 12px;font-size:12px}.table{width:100%;border-collapse:collapse}.table td,.table th{text-align:right;padding:11px;border-bottom:1px solid #342718}.table-wrap{overflow:auto}.table{min-width:800px}</style></head><body><main class="wrap"><a class="text-link" href="index.php">← لوحة التحكم</a><h1>إدارة الطلبات</h1><nav class="filters"><a href="orders.php">الكل</a><?php foreach(['new'=>'جديدة','reviewing'=>'مراجعة','accepted'=>'مقبولة','preparing'=>'قيد التجهيز','ready'=>'جاهزة','completed'=>'مكتملة','rejected'=>'مرفوضة','cancelled'=>'ملغاة'] as $k=>$v):?><a href="?status=<?=$k?>"><?=e($v)?></a><?php endforeach;?></nav><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>رقم الطلب</th><th>العميل</th><th>الهاتف</th><th>التاريخ</th><th>الاستلام</th><th>الإجمالي</th><th>الحالة</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['order_number'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['created_at'])?></td><td><?=e($r['fulfillment_method'])?></td><td><?=number_format((float)$r['total'],2)?> ر.س</td><td><?=e($r['status'])?></td><td><a class="btn btn-outline" href="order.php?id=<?=(int)$r['id']?>">التفاصيل</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8">لا توجد طلبات مطابقة.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>